const pptxgen = require("pptxgenjs");
const slideConfig = {
  type: 'cover',
  index: 1,
  title: "Scale SEAL Leaderboards: Frontier Model Performance Across 20+ Benchmarks"
};

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: theme.bg };

  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 10, h: 5.625,
    fill: { color: theme.primary }
  });

  slide.addText(slideConfig.title, {
    x: 1, y: 1.5, w: 8, h: 1.5,
    fontSize: 36, fontFace: "Arial",
    color: "FFFFFF", bold: true, align: "center", valign: "middle"
  });

  slide.addText("A comparative analysis of top-performing AI models across Scale Labs' benchmark suite\nspanning agentic coding, reasoning, safety, and multimodal capabilities.", {
    x: 1, y: 3.2, w: 8, h: 1,
    fontSize: 18, fontFace: "Arial",
    color: theme.light, align: "center", valign: "top"
  });

  slide.addShape(pres.shapes.LINE, {
    x: 4.5, y: 3.0, w: 1, h: 0,
    line: { color: theme.accent, width: 2 }
  });

  slide.addText("Scale Labs | 100+ Models Evaluated", {
    x: 1, y: 4.5, w: 8, h: 0.5,
    fontSize: 14, fontFace: "Arial",
    color: theme.light, align: "center", valign: "middle", bold: true
  });

  return slide;
}
module.exports = { createSlide, slideConfig };

const pptxgen = require("pptxgenjs");
const slideConfig = {
  type: 'content',
  index: 2,
  title: "20+ Benchmarks Spanning Four Capability Domains Evaluate 100+ Models"
};
function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: theme.bg };

  // Title
  slide.addText(slideConfig.title, {
    x: 0.5, y: 0.3, w: 9, h: 0.6,
    fontSize: 24, fontFace: "Arial",
    color: theme.primary, bold: true
  });
  slide.addShape(pres.shapes.LINE, {
    x: 0.5, y: 1.0, w: 9, h: 0,
    line: { color: theme.accent, width: 2 }
  });

  const domains = [
    { title: "Agentic", subtitle: "Coding & Tool Use", color: "10A37F", examples: "SWE Atlas\nMCP Atlas\nSWE-Bench Pro" },
    { title: "Frontier", subtitle: "Reasoning & Knowledge", color: "2563EB", examples: "Humanity's Last Exam\nEnigmaEval\nMultiChallenge\nSciPredict" },
    { title: "Safety", subtitle: "Alignment & Honesty", color: "D97757", examples: "MASK\nPropensityBench\nFortress\nProfessional Reasoning" },
    { title: "Multimodal", subtitle: "Audio & Vision-Language", color: "9333EA", examples: "AudioMultiChallenge\nVISTA\nVisualToolBench" }
  ];

  domains.forEach((d, i) => {
    const xPos = 0.5 + i * 2.3;
    slide.addShape(pres.shapes.RECTANGLE, {
      x: xPos, y: 1.5, w: 2.1, h: 3.2,
      fill: { color: "FFFFFF" },
      line: { color: theme.light, width: 1 }
    });
    slide.addShape(pres.shapes.RECTANGLE, {
      x: xPos, y: 1.5, w: 2.1, h: 0.8,
      fill: { color: d.color }
    });
    slide.addText(d.title, {
      x: xPos, y: 1.5, w: 2.1, h: 0.5,
      fontSize: 18, fontFace: "Arial",
      color: "FFFFFF", bold: true, align: "center", valign: "bottom"
    });
    slide.addText(d.subtitle, {
      x: xPos, y: 2.0, w: 2.1, h: 0.3,
      fontSize: 12, fontFace: "Arial",
      color: "F8FAFC", align: "center", valign: "top"
    });
    slide.addText(d.examples, {
      x: xPos + 0.1, y: 2.5, w: 1.9, h: 2.0,
      fontSize: 14, fontFace: "Arial",
      color: theme.secondary, align: "center", valign: "top", bullet: true
    });
  });

  // Badge
  slide.addShape(pres.shapes.ROUNDED_RECTANGLE, {
    x: 9.1, y: 5.15, w: 0.6, h: 0.35,
    fill: { color: theme.accent },
    rectRadius: 0.15
  });
  slide.addText("02", {
    x: 9.1, y: 5.15, w: 0.6, h: 0.35,
    fontSize: 11, fontFace: "Arial",
    color: "FFFFFF", bold: true, align: "center", valign: "middle"
  });

  return slide;
}
module.exports = { createSlide, slideConfig };

