const pptxgen = require("pptxgenjs");
const slideConfig = {
  type: 'content',
  index: 7,
  title: "OpenAI, Google, and Anthropic Each Claim #1 Across Different Domains"
};
function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: theme.bg };

  slide.addText(slideConfig.title, {
    x: 0.5, y: 0.3, w: 9, h: 0.6,
    fontSize: 20, fontFace: "Arial",
    color: theme.primary, bold: true
  });
  slide.addShape(pres.shapes.LINE, {
    x: 0.5, y: 1.0, w: 9, h: 0,
    line: { color: theme.accent, width: 2 }
  });

  const headers = ["Domain", "Benchmark", "Leading Lab", "#1 Model", "Score"];
  const rows = [
    ["Agentic", "SWE Atlas (Test Writing)", "OpenAI", "GPT-5.4-xHigh", "44.4"],
    ["Agentic", "SWE-Bench Pro (Public)", "OpenAI", "GPT-5.4-pro", "59.1"],
    ["Agentic", "SWE-Bench Pro (Private)", "Anthropic", "Claude Opus 4.6", "47.1"],
    ["Agentic", "MCP Atlas (Tool Use)", "Muse", "Muse Spark", "78.3"],
    ["Frontier", "Humanity's Last Exam", "OpenAI", "GPT-5.4-pro", "44.3"],
    ["Frontier", "MultiChallenge", "Muse", "Muse Spark", "75.5"],
    ["Safety", "MASK (Honesty)", "Anthropic", "Claude Opus 4.6", "96.3"],
    ["Multimodal", "Audio Output", "Google", "Gemini 3.1 Flash Live", "36.1"],
    ["Multimodal", "VISTA (Vision-Lang)", "Google", "Gemini 2.5 Pro", "54.7"]
  ];

  const tableData = [
    headers.map(text => ({ text, options: { bold: true, color: "FFFFFF", fill: theme.primary, fontFace: "Arial", fontSize: 12 } }))
  ];

  rows.forEach(row => {
    let labColor = "FFFFFF";
    if (row[2] === "OpenAI") labColor = "E6F4EA"; // Light Green
    if (row[2] === "Google") labColor = "E8F0FE"; // Light Blue
    if (row[2] === "Anthropic") labColor = "FCE8E6"; // Light Red/Orange
    if (row[2] === "Muse") labColor = "F3E8FD"; // Light Purple

    tableData.push(
      row.map(text => ({ text, options: { fill: labColor, color: theme.primary, fontSize: 12, fontFace: "Arial" } }))
    );
  });

  slide.addTable(tableData, {
    x: 0.5, y: 1.3, w: 9,
    colW: [1.5, 2.5, 1.5, 2.5, 1.0],
    border: { type: "solid", pt: 1, color: "FFFFFF" }
  });

  slide.addText("Muse Spark enters as a prominent competitor, capturing #1 in Tool Use (78.3%) and MultiChallenge (75.5%).", {
    x: 0.5, y: 4.8, w: 9, h: 0.4,
    fontSize: 14, fontFace: "Arial",
    color: theme.secondary, italic: true
  });

  // Badge
  slide.addShape(pres.shapes.ROUNDED_RECTANGLE, {
    x: 9.1, y: 5.15, w: 0.6, h: 0.35,
    fill: { color: theme.accent },
    rectRadius: 0.15
  });
  slide.addText("07", {
    x: 9.1, y: 5.15, w: 0.6, h: 0.35,
    fontSize: 11, fontFace: "Arial",
    color: "FFFFFF", bold: true, align: "center", valign: "middle"
  });

  return slide;
}
module.exports = { createSlide, slideConfig };

